solution:
def clamp(n, low, high):
    return max(low, min(n, high))


assert clamp(5, 0, 3) == 3
assert clamp(-1, 0, 3) == 0

alt:
def clamp(n, low, high):
    if n < low:
        return low
    if n > high:
        return high
    return n


assert clamp(2, 0, 3) == 2
assert clamp(9, 0, 3) == 3
assert clamp(-4, 0, 3) == 0
